#!/bin/bash
set -eo pipefail
test "$(id -un)" = sunyiq
timeout --signal=KILL 20 /data1/home/sunyiq/miniconda3/envs/nh_final/bin/python -I -B - <<'FIXED_FLOW_PATHS_PYTHON'
import base64, datetime, gzip, hashlib, json, signal
source = base64.b64decode('', validate=True)
if hashlib.sha256(source).hexdigest() != '13a63c86994ae5208cba5cb645ca904fad21b25b0fcfeba44537e26fb642d5a6':
    raise ValueError('Reviewed metadata reader bytes differ')
namespace = {'__name__': 'fixed_path_metadata_scope'}
exec(compile(source, '<fixed_flow_path_metadata_v1>', 'exec'), namespace)
def expired(_signal, _frame):
    raise TimeoutError('Ten-second exact path metadata bound')
signal.signal(signal.SIGALRM, expired)
signal.alarm(10)
report = namespace['inspect']()
signal.alarm(0)
report.update(reader_sha256='13a63c86994ae5208cba5cb645ca904fad21b25b0fcfeba44537e26fb642d5a6', server_timestamp=datetime.datetime.now(datetime.timezone(datetime.timedelta(hours=8))).isoformat())
raw = json.dumps(report, ensure_ascii=True, separators=(',', ':'), allow_nan=False).encode()
if len(raw) > 65536:
    raise ValueError('Metadata report byte bound')
print('FLOW_PATHS_REPORT_SHA256='+hashlib.sha256(raw).hexdigest())
print('FLOW_PATHS_GZIP_BASE64_BEGIN')
print(base64.b64encode(gzip.compress(raw, mtime=0)).decode())
print('FLOW_PATHS_GZIP_BASE64_END')
FIXED_FLOW_PATHS_PYTHON
printf 'FLOW_PATHS_QUERY_COMPLETE\n'
